#!/usr/bin/env dotnet
// Explore Friday the 13th in the proleptic Gregorian calendar

// Find the earliest Friday the 13th starting from 0001-01-01
var date = new DateTime(1, 1, 13); // start checking the 13th of each month
DateTime? earliest = null;

while (date.Year == 1)
{
    if (date.DayOfWeek == DayOfWeek.Friday)
    {
        earliest = date;
        break;
    }
    date = date.AddMonths(1);
}

// If not found in year 1, keep searching
if (earliest is null)
{
    date = new DateTime(2, 1, 13);
    while (true)
    {
        if (date.DayOfWeek == DayOfWeek.Friday)
        {
            earliest = date;
            break;
        }
        date = date.AddMonths(1);
    }
}

Console.WriteLine($"Earliest Friday the 13th: {earliest:yyyy-MM-dd} ({earliest:dddd})");
Console.WriteLine();

// Count Friday the 13ths in a full 400-year cycle (the Gregorian calendar repeats every 400 years)
int count = 0;
var start = new DateTime(1, 1, 13);
var end = new DateTime(401, 1, 1);

date = start;
while (date < end)
{
    if (date.DayOfWeek == DayOfWeek.Friday)
        count++;
    date = date.AddMonths(1);
}

Console.WriteLine($"Friday the 13ths in a 400-year cycle: {count}");
Console.WriteLine($"Average per year: {count / 400.0:F4}");
Console.WriteLine();

// Bonus: which day-of-week is the 13th most likely to fall on?
var dayCounts = new int[7];
date = start;
while (date < end)
{
    dayCounts[(int)date.DayOfWeek]++;
    date = date.AddMonths(1);
}

Console.WriteLine("Distribution of the 13th by day of week (400-year cycle):");
foreach (DayOfWeek day in Enum.GetValues<DayOfWeek>())
{
    Console.WriteLine($"  {day,-10} {dayCounts[(int)day],4}");
}

